import { NextRequest, NextResponse } from "next/server";
import { extractDocumentData } from "../../../lib/llm";

export async function POST(req: NextRequest) {
  try {
    const { prompt, templateId } = await req.json();

    if (!prompt || !templateId) {
      return NextResponse.json({ error: "Missing prompt or templateId" }, { status: 400 });
    }

    // Mocking the required fields for testing since your database has no templates yet
    const requiredFields = ["eventName", "date", "venue", "budget", "facultyCoordinator"]; 

    const extractionResult = await extractDocumentData(prompt, requiredFields);

    return NextResponse.json(extractionResult, { status: 200 });
  } catch (error) {
    console.error("Extraction error:", error);
    return NextResponse.json({ error: "Failed to extract data" }, { status: 500 });
  }
}