import { GoogleGenAI, Type, Schema } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

export async function extractDocumentData(
  prompt: string,
  requiredFields: string[]
): Promise<any> {
  const propertiesSchema: Record<string, Schema> = {};
  requiredFields.forEach((field) => {
    propertiesSchema[field] = {
      type: Type.STRING,
      description: `Extract or infer the value for ${field}. If unknown, omit it. Do NOT make up dummy data.`,
    };
  });

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: {
      extractedData: {
        type: Type.OBJECT,
        properties: propertiesSchema,
      },
      missingFields: {
        type: Type.ARRAY,
        items: { type: Type.STRING },
        description: "List of required fields that are missing from the prompt.",
      },
      clarificationQuestion: {
        type: Type.STRING,
        description: "A natural question asking the user for the missing fields.",
      },
    },
    required: ["extractedData", "missingFields"],
  };

  const systemInstruction = `You are a strict data extraction assistant for official university documents. 
  RULE 1: NEVER hallucinate, guess, or invent dates, names, venues, or budgets.
  RULE 2: If a required field is missing from the user's prompt, do NOT insert placeholders like 'TBD' or '[Insert]'. Simply leave it out of extractedData, add it to missingFields, and formulate a clarificationQuestion.
  RULE 3: The required fields are: ${requiredFields.join(", ")}.`;

  let attempt = 0;
  const maxRetries = 3;

  while (attempt < maxRetries) {
    try {
      const response = await ai.models.generateContent({
        model: "gemini-3.8-flash", // Back to the correct, active model
        contents: prompt,
        config: {
          systemInstruction: systemInstruction,
          responseMimeType: "application/json",
          responseSchema: responseSchema,
          temperature: 0.0,
        },
      });

      let result = response.text;
      if (!result) throw new Error("LLM returned empty response");
      
      // Clean up any stray markdown formatting
      result = result.replace(/```json/g, "").replace(/```/g, "").trim();
      return JSON.parse(result);

    } catch (error: any) {
      // If the error is a 503 (Server Busy), wait and retry
      if (error.status === 503 || (error.message && error.message.includes("503"))) {
        attempt++;
        console.warn(`[API 503] Server busy. Retrying attempt ${attempt}...`);
        if (attempt >= maxRetries) throw new Error("Gemini API is currently overloaded. Please try again in a few moments.");
        
        // Wait 1.5 seconds before trying again
        await new Promise((resolve) => setTimeout(resolve, 1500));
      } else {
        // If it's a different error (like a 404 or bad API key), throw it immediately
        throw error; 
      }
    }
  }
}